// Combine the engine's editable-param schema with the user's request.
// Only the schema for the currently-selected models is sent to the LLM,
// which keeps the prompt (and token cost) small.

const trigger = $('When Executed by Another Workflow').first().json;
const schemaResp = $input.first().json;

const fullSchema = schemaResp.schema || {};
const selected = Array.isArray(trigger.selected_models)
  ? trigger.selected_models
  : [];
const userMessage = (trigger.user_message || '').toString().trim();

// Slim schema -> only selected models, only what the LLM needs.
const slim = {};
for (const name of selected) {
  const spec = fullSchema[name];
  if (!spec) continue;
  const params = {};
  for (const [p, meta] of Object.entries(spec.params || {})) {
    params[p] = {
      type: meta.type,
      default: meta.default,
      ...(meta.min !== undefined ? { min: meta.min } : {}),
      ...(meta.max !== undefined ? { max: meta.max } : {}),
      ...(meta.choices !== undefined ? { choices: meta.choices } : {}),
      ...(meta.nullable ? { nullable: true } : {})
    };
  }
  slim[name] = params;
}

const userPrompt =
  'Selected models and their editable hyperparameters (with valid ranges):\n' +
  JSON.stringify(slim, null, 2) +
  '\n\nUser request: "' + userMessage + '"\n\n' +
  'Return the JSON patch now.';

return [{
  json: {
    chatId: trigger.chatId,
    problem_type: trigger.problem_type,
    target_column: trigger.target_column,
    dataset_path: trigger.dataset_path,
    dataset_name: trigger.dataset_name,
    selected_models: selected,
    slim_schema: slim,
    user_message: userMessage,
    user_prompt: userPrompt
  }
}];

// Defensively parse the LLM output and merge it into recommended_models.
// The engine re-validates and clamps everything server-side, so this node
// only needs to produce well-formed structure and never crash on bad output.

const ctx = $('Build AI Prompt').first().json;
const selected = ctx.selected_models || [];
const slim = ctx.slim_schema || {};

let raw = $input.first().json;
let text = raw.output ?? raw.text ?? raw.response ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);

// Strip markdown fences / surrounding prose, keep the outermost JSON object.
function extractJson(s) {
  if (!s) return {};
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1 || end < start) return {};
  try {
    return JSON.parse(s.slice(start, end + 1));
  } catch (e) {
    return {};
  }
}

const patch = extractJson(text);

// Build recommended_models: every selected model, with AI params where given.
// Keep only params that exist in that model's schema (belt-and-suspenders;
// the engine also drops unknowns).
const recommended_models = selected.map((name, index) => {
  const allowed = slim[name] || {};
  const proposed = (patch && typeof patch === 'object' && patch[name]) ? patch[name] : {};
  const params = {};
  for (const [k, v] of Object.entries(proposed)) {
    if (k in allowed) params[k] = v;
  }
  return { priority: index + 1, name, params };
});

// Human-readable summary of what changed, for a Telegram confirmation.
const changed = recommended_models.filter(m => Object.keys(m.params).length > 0);
let summary;
if (changed.length === 0) {
  summary = 'No hyperparameter changes were applied (using defaults).';
} else {
  summary = changed.map(m => {
    const kv = Object.entries(m.params).map(([k, v]) => `${k}=${v}`).join(', ');
    return `• ${m.name}: ${kv}`;
  }).join('\n');
}

return [{
  json: {
    chatId: ctx.chatId,
    problem_type: ctx.problem_type,
    target_column: ctx.target_column,
    dataset_path: ctx.dataset_path,
    dataset_name: ctx.dataset_name,
    selected_models: selected,
    recommended_models,
    customization_summary: summary,
    ai_raw: text
  }
}];
